const ep = $input.first().json.body;
const episodeId = ep.episodeId ?? Math.floor(Math.random() * 900) + 100;
const title = ep.title ?? 'Untitled episode';
const agents = [
  ['akira', `Routing → 4 clip queues · EP${episodeId}`],
  ['nova', `Silence-trim · EP${episodeId}`],
  ['hook', `Drafting hooks · EP${episodeId}`],
  ['lexa', `Karaoke captions ID/EN · EP${episodeId}`],
  ['pixel', `A/B testing covers · EP${episodeId}`],
  ['bolt', `Render & ship · EP${episodeId}`],
];
return agents.map(([agentId, jobTitle]) => ({
  json: { episodeId, title, agentId, jobTitle, queuedAt: Date.now() },
}));
